sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
  try {
    var result;
    var __result = (function() {
      function ins(v){ var g=new GlideRecord('pa_indicators'); g.addQuery('name',v.name); g.query(); if(g.next()) return g.getUniqueValue(); g.initialize(); for(var k in v) g.setValue(k,v[k]); return g.insert(); }
      var base={type:'1',cube:'61fe492c2be81f90b7b1f93a5e91bf7d',aggregate:'2',frequency:'10',unit:'20c365e2d7320100ba986f14ce6103b3',precision:'0',collect_records:'true',collect_breakdown_matrix:'true',display:'true',value_when_nil:'0',forecast_periods:'2',forecast_base_periods:'2'};
      function mk(extra){ var o={}; for(var k in base) o[k]=base[k]; for(var j in extra) o[j]=extra[j]; return o; }
      var a=ins(mk({name:'DPM: Annual run cost',field:'cost',direction:'2',description:'Annual run cost allocated to each service offering (service_offering.cost), summed up through services, taxonomy nodes, and portfolios. Demo values are estimates allocated from the FY27 OST appropriation (Act 145).'}));
      var b=ins(mk({name:'DPM: Annual cost avoided',field:'x_snc_sas_positi_0_u_annual_cost_avoided',direction:'1',description:'Estimated annual cost the state avoids by delivering each offering on the shared platform instead of a separate vendor build (vendor estimate minus OST run cost). Demo values are estimates.'}));
      if(!a||!b) throw new Error('insert failed a='+a+' b='+b);
      ; if (typeof result !== 'undefined') return result;
    })();
    response.setBody({ success: true, result: (__result === undefined ? null : __result) });
  } catch(e) {
    response.setBody({ success: false, error: e + '', message: e.message || (e + '') });
  }
})(request, response);
